# Completes the value after `=` in $1 from the words in $2.
_obsbot4linux_assign() {
    local key=${1%%=*} val=${1#*=}
    local -a found
    mapfile -t found < <(compgen -W "$2" -- "$val")
    if [[ $COMP_WORDBREAKS == *=* ]]; then
        COMPREPLY=("${found[@]}")
    else
        COMPREPLY=("${found[@]/#/$key=}")
    fi
}

_obsbot4linux() {
    local line=${COMP_LINE:0:COMP_POINT}
    local -a words
    read -r -a words <<< "$line"
    local cur=''
    if [[ $line != *[[:space:]] ]]; then
        cur=${words[${#words[@]}-1]}
        unset 'words[${#words[@]}-1]'
    fi
    local prev=${words[${#words[@]}-1]}
    local sub='' action='' i=1 w
    while (( i < ${#words[@]} )); do
        w=${words[i]}
        case $w in
            --device) (( i += 2 )); continue ;;
            -*) ;;
            *)
                if [[ -z $sub ]]; then
                    sub=$w
                elif [[ $sub == do && -z $action ]]; then
                    action=$w
                fi
                ;;
        esac
        (( i++ ))
    done
    local cands='' nospace='' REPLY=''
    if [[ $prev == --device ]]; then
        COMPREPLY=()
        return
    elif [[ $cur == -* ]]; then
        case $sub in
            devices) cands='--report --json --device --help --version' ;;
            watch) cands='--live --json --device --help --version' ;;
            *) cands='--json --device --help --version' ;;
        esac
    elif [[ -z $sub ]]; then
        cands='status get set do describe devices watch'
    else
        case $sub in
            get) cands=$_obsbot4linux_get_paths ;;
            describe) cands=$_obsbot4linux_describe_names ;;
            set)
                if [[ $cur == *=* ]]; then
                    _obsbot4linux_values "${cur%%=*}"
                    _obsbot4linux_assign "$cur" "$REPLY"
                    return
                fi
                cands=$_obsbot4linux_set_paths
                nospace=1
                ;;
            do)
                if [[ -z $action ]]; then
                    cands=$_obsbot4linux_actions
                elif [[ $cur == *=* ]]; then
                    _obsbot4linux_values "$action ${cur%%=*}"
                    _obsbot4linux_assign "$cur" "$REPLY"
                    return
                else
                    _obsbot4linux_params "$action"
                    cands=$REPLY
                    nospace=1
                fi
                ;;
            watch) cands='auto pose target' ;;
        esac
    fi
    mapfile -t COMPREPLY < <(compgen -W "$cands" -- "$cur")
    if [[ -n $nospace ]]; then
        compopt -o nospace 2>/dev/null
    fi
}

complete -F _obsbot4linux obsbot4linux
